  [string]$InstallDir = "$env:LOCALAPPDATA\\ERP2-Analytics-HostAgent",
  [switch]$NoPause = $false
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Write-Info([string] $m) { Write-Host ("[INFO] " + $m) -ForegroundColor Cyan }
function Write-Err([string] $m) { Write-Host ("[ERR] " + $m) -ForegroundColor Red }
function Write-Warn([string] $m) { Write-Host ("[WARN] " + $m) -ForegroundColor Yellow }

function Test-HostAgentTaskExists([string]$TaskName) {
  $null = & schtasks.exe /Query /TN "$TaskName" 2>$null
  return ($LASTEXITCODE -eq 0)
}

function Get-HostAgentTaskCommand([string]$TaskName) {
  $output = @(& schtasks.exe /Query /TN "$TaskName" /FO LIST /V 2>$null)
  if ($LASTEXITCODE -ne 0) { return "" }
  $joined = (($output | ForEach-Object { "$_" }) -join [Environment]::NewLine)
  $line = ($joined -split "`r?`n" | Where-Object { $_ -match "host-agent\.ps1|start-host-agent\.ps1|ERP2-Analytics-HostAgent" } | Select-Object -First 1)
  return [string]($line ?? "")
}

function Register-HostAgentTask([string]$TaskName, [string]$TaskRunCommand) {
  $output = @(& schtasks.exe /Create /TN "$TaskName" /TR "$TaskRunCommand" /SC ONLOGON /RL LIMITED /F 2>&1)
  $exitCode = $LASTEXITCODE
  if ($exitCode -eq 0) { return @{ reusedExisting = $false } }

  $detail = (($output | ForEach-Object { "$_" }) -join [Environment]::NewLine).Trim()
  if ([string]::IsNullOrWhiteSpace($detail)) {
    $detail = "schtasks.exe exited with code $exitCode"
  }

  if (Test-HostAgentTaskExists -TaskName $TaskName) {
    $currentTaskCommand = Get-HostAgentTaskCommand -TaskName $TaskName
    $resolvedInstallDir = [string](Resolve-Path -LiteralPath $InstallDir -ErrorAction SilentlyContinue)
    if ([string]::IsNullOrWhiteSpace($resolvedInstallDir)) { $resolvedInstallDir = [string]$InstallDir }
    $pointsAtInstallDir = $currentTaskCommand -and (
      $currentTaskCommand -like ("*" + $resolvedInstallDir + "*") -or
      $currentTaskCommand -like "*ERP2-Analytics-HostAgent*"
    )
    $portsOk = $currentTaskCommand -like "*-Port $Port*" -and $currentTaskCommand -like "*-CdpPort $CdpPort*"
    if ($pointsAtInstallDir -and $portsOk) {
      Write-Warn ("Task '{0}' could not be overwritten, but it already points to this install dir/ports. Reusing it." -f $TaskName)
      return @{ reusedExisting = $true; detail = $detail }
    }
    throw ("Task Scheduler registration failed for '{0}', and the existing command does not match this install dir/ports.`nCurrent command: {1}`nExpected command: {2}`nFix: run as administrator: schtasks /Delete /TN `"{0}`" /F, then install again.`nOriginal message: {3}" -f $TaskName, $currentTaskCommand, $TaskRunCommand, $detail)
  }

  throw ("Task Scheduler registration failed: {0}" -f $detail)
}

# Windows PowerShell(5.1)�??�행?�면 pwsh�??�실??가?�하�?
if ($PSVersionTable.PSVersion.Major -lt 7) {
  $pwshCmd0 = Get-Command pwsh -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($pwshCmd0 -and $pwshCmd0.Source) {
    Start-Process -FilePath $pwshCmd0.Source -ArgumentList @(
      "-NoProfile",
      "-ExecutionPolicy", "Bypass",
      "-File", $PSCommandPath,
      "-Port", $Port,
      "-CdpPort", $CdpPort,
      "-InstallDir", $InstallDir,
      "-NoPause:$NoPause"
    ) -WindowStyle Normal -Wait | Out-Null
    exit 0
  }
}

function Write-TextUtf8NoBom([string] $path, [string] $content) {
  $dir = Split-Path -Parent $path
  if ($dir -and (-not (Test-Path -LiteralPath $dir))) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  $utf8NoBom = New-Object System.Text.UTF8Encoding($false)
  [System.IO.File]::WriteAllText($path, $content, $utf8NoBom)
}

function Register-HostAgentStartProtocol([string]$StartScriptPath) {
  $protocolRoot = "HKCU:\Software\Classes\erp2-analytics-host-agent"
  $commandKey = Join-Path $protocolRoot "shell\open\command"
  New-Item -Path $commandKey -Force | Out-Null
  New-ItemProperty -Path $protocolRoot -Name "URL Protocol" -Value "" -PropertyType String -Force | Out-Null
  Set-Item -Path $protocolRoot -Value "URL:ERP2 Analytics Host Agent"
  # 브라?��?/UI???�동 ?�시??경로???�공 ?�내 창을 ?�기지 ?�는??
  # ?�동 ?�치 ?�행기만 마�?�??�내/?��?창을 ?��??�다.
  $command = "`"$pwsh`" -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$StartScriptPath`" -Port $Port -CdpPort $CdpPort -NoPause `"%1`""
  Set-Item -Path $commandKey -Value $command
}

function Add-UniquePath([System.Collections.Generic.List[string]]$Items, [string]$Value) {
  if ([string]::IsNullOrWhiteSpace($Value)) { return }
  $normalized = $Value.Trim()
  if (-not $Items.Contains($normalized)) { $Items.Add($normalized) }
}

function Resolve-PowerShellExe {
  $candidates = New-Object 'System.Collections.Generic.List[string]'
  $pshomePwsh = $null
  $pshomeWindows = $null
  if (-not [string]::IsNullOrWhiteSpace($PSHOME)) {
    $pshomePwsh = Join-Path $PSHOME 'pwsh.exe'
    $pshomeWindows = Join-Path $PSHOME 'powershell.exe'
  }
  foreach ($value in @(
    $pshomePwsh,
    $pshomeWindows,
    "$env:ProgramFiles\PowerShell\7\pwsh.exe",
    "$env:ProgramFiles\PowerShell\6\pwsh.exe",
    "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
  )) {
    if (-not [string]::IsNullOrWhiteSpace($value) -and -not $candidates.Contains($value)) { $candidates.Add($value) | Out-Null }
  }
  foreach ($candidate in $candidates) {
    if (Test-Path -LiteralPath $candidate) { return $candidate }
  }
  $pwshCmd = Get-Command pwsh -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($pwshCmd -and $pwshCmd.Source) { return $pwshCmd.Source }
  $powershellCmd = Get-Command powershell -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($powershellCmd -and $powershellCmd.Source) { return $powershellCmd.Source }
  throw "PowerShell executable was not found."
}

function Add-ParentCandidates([System.Collections.Generic.List[string]]$Items, [string]$StartPath) {
  if ([string]::IsNullOrWhiteSpace($StartPath)) { return }
  $current = $StartPath
  while (-not [string]::IsNullOrWhiteSpace($current)) {
    Add-UniquePath $Items $current
    $canonicalFile = Join-Path $current "CANONICAL_ROOT.txt"
    if (Test-Path -LiteralPath $canonicalFile) {
      try {
        $canonicalRoot = (Get-Content -LiteralPath $canonicalFile -TotalCount 1 -ErrorAction Stop | Select-Object -First 1).Trim()
        Add-UniquePath $Items $canonicalRoot
      } catch {}
    }
    $parent = Split-Path -Parent $current
    if ([string]::IsNullOrWhiteSpace($parent) -or $parent -eq $current) { break }
    $current = $parent
  }
}

function Resolve-AnalyticsRepoRoot {
  $candidates = New-Object 'System.Collections.Generic.List[string]'
  Add-UniquePath $candidates $env:ERP2_ANALYTICS_ROOT
  Add-ParentCandidates $candidates $PSScriptRoot
  try { Add-ParentCandidates $candidates ((Get-Location).Path) } catch {}
  try {
    foreach ($driveRoot in (Get-PSDrive -PSProvider FileSystem | Select-Object -ExpandProperty Root)) {
      Add-UniquePath $candidates (Join-Path $driveRoot "dev\ERP2-analytics")
    }
  } catch {}
  Add-UniquePath $candidates "D:\dev\ERP2-analytics"
  Add-UniquePath $candidates "C:\dev\ERP2-analytics"

  foreach ($root in $candidates) {
    $agent = Join-Path $root "tools\host-agent.ps1"
    $start = Join-Path $root "tools\start-host-agent.ps1"
    $ensure = Join-Path $root "tools\ensure-host-agent.ps1"
    $menuScript = Join-Path $root "scripts\menu-sync-db-reconcile.ps1"
    if (
      (Test-Path -LiteralPath $agent) -and
      (Test-Path -LiteralPath $start) -and
      (Test-Path -LiteralPath $ensure) -and
      (Test-Path -LiteralPath $menuScript)
    ) {
      return $root
    }
  }
  return $null
}

