$ensureScript = @'
param(
  [int]$Port = 9230,
  [int]$CdpPort = 9223
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Resolve-PowerShellExe {
  $candidates = New-Object 'System.Collections.Generic.List[string]'
  $pshomePwsh = $null
  $pshomeWindows = $null
  if (-not [string]::IsNullOrWhiteSpace($PSHOME)) {
    $pshomePwsh = Join-Path $PSHOME 'pwsh.exe'
    $pshomeWindows = Join-Path $PSHOME 'powershell.exe'
  }
  foreach ($value in @(
    $pshomePwsh,
    $pshomeWindows,
    "$env:ProgramFiles\PowerShell\7\pwsh.exe",
    "$env:ProgramFiles\PowerShell\6\pwsh.exe",
    "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
  )) {
    if (-not [string]::IsNullOrWhiteSpace($value) -and -not $candidates.Contains($value)) { $candidates.Add($value) | Out-Null }
  }
  foreach ($candidate in $candidates) {
    if (Test-Path -LiteralPath $candidate) { return $candidate }
  }
  $pwshCmd = Get-Command pwsh -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($pwshCmd -and $pwshCmd.Source) { return $pwshCmd.Source }
  $powershellCmd = Get-Command powershell -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($powershellCmd -and $powershellCmd.Source) { return $powershellCmd.Source }
  throw "PowerShell executable was not found."
}

function Test-AgentHealthy([int]$port) {
  try {
    $r = Invoke-WebRequest -UseBasicParsing -Uri ("http://127.0.0.1:{0}/health" -f $port) -TimeoutSec 1
    return ($r -and $r.StatusCode -ge 200 -and $r.StatusCode -lt 300)
  } catch { return $false }
}

function Ensure-BackgroundWorker([int]$port) {
  $configPath = Join-Path "$env:LOCALAPPDATA\ERP2-Analytics-HostChrome" "collector-background.config.json"
  if (-not (Test-Path -LiteralPath $configPath)) { return }
  try {
    $status = Invoke-RestMethod -Method Get -Uri ("http://127.0.0.1:{0}/collector/background/status" -f $port) -TimeoutSec 2
    if ($status -and $status.running) { return }
  } catch {}
  try {
    $raw = Get-Content -LiteralPath $configPath -Raw -ErrorAction Stop
    if ([string]::IsNullOrWhiteSpace($raw)) { return }
    $cfg = $raw | ConvertFrom-Json
    $bearerToken = [string]($cfg.bearerToken ?? "")
    $collectorToken = [string]($cfg.collectorToken ?? "")
    if ([string]::IsNullOrWhiteSpace($bearerToken) -and [string]::IsNullOrWhiteSpace($collectorToken)) { return }
    Invoke-RestMethod -Method Post -Uri ("http://127.0.0.1:{0}/collector/background/start" -f $port) -ContentType "application/json" -Body $raw -TimeoutSec 5 | Out-Null
  } catch {}
}

if (Test-AgentHealthy -port $Port) {
  Ensure-BackgroundWorker -port $Port
  exit 0
}

$agent = Join-Path $PSScriptRoot "tools\host-agent.ps1"
$pwshExe = Resolve-PowerShellExe
Start-Process -FilePath $pwshExe -ArgumentList @(
  "-NoProfile",
  "-ExecutionPolicy", "Bypass",
  "-File", $agent,
  "-Port", $Port,
  "-CdpPort", $CdpPort
) -WindowStyle Hidden | Out-Null

for ($i = 0; $i -lt 20; $i++) {
  Start-Sleep -Milliseconds 500
  if (Test-AgentHealthy -port $Port) {
    Ensure-BackgroundWorker -port $Port
    exit 0
  }
}
'@

$startScript = @'
param(
  [int]$Port = 9230,
  [int]$CdpPort = 9223,
  [switch]$NoPause = $false,
  [string]$ProtocolUrl = ""
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Resolve-PowerShellExe {
  $candidates = New-Object 'System.Collections.Generic.List[string]'
  $pshomePwsh = $null
  $pshomeWindows = $null
  if (-not [string]::IsNullOrWhiteSpace($PSHOME)) {
    $pshomePwsh = Join-Path $PSHOME 'pwsh.exe'
    $pshomeWindows = Join-Path $PSHOME 'powershell.exe'
  }
  foreach ($value in @(
    $pshomePwsh,
    $pshomeWindows,
    "$env:ProgramFiles\PowerShell\7\pwsh.exe",
    "$env:ProgramFiles\PowerShell\6\pwsh.exe",
    "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
  )) {
    if (-not [string]::IsNullOrWhiteSpace($value) -and -not $candidates.Contains($value)) { $candidates.Add($value) | Out-Null }
  }
  foreach ($candidate in $candidates) {
    if (Test-Path -LiteralPath $candidate) { return $candidate }
  }
  $pwshCmd = Get-Command pwsh -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($pwshCmd -and $pwshCmd.Source) { return $pwshCmd.Source }
  $powershellCmd = Get-Command powershell -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($powershellCmd -and $powershellCmd.Source) { return $powershellCmd.Source }
  throw "PowerShell executable was not found."
}

$installedAgent = Join-Path $PSScriptRoot "tools\host-agent.ps1"

function Test-AgentHealthy([int]$port) {
  try {
    $r = Invoke-WebRequest -UseBasicParsing -Uri ("http://127.0.0.1:{0}/health" -f $port) -TimeoutSec 1
    return ($r -and $r.StatusCode -ge 200 -and $r.StatusCode -lt 300)
  } catch {
    return $false
  }
}

function Stop-ExistingHostAgents([int]$port) {
  try {
    Invoke-RestMethod -Method Post -Uri ("http://127.0.0.1:{0}/shutdown" -f $port) -TimeoutSec 2 | Out-Null
    Start-Sleep -Milliseconds 700
  } catch {
    # The process may already be down or blocked before the listener responds.
  }

  try {
    $currentPid = $PID
    $processes = Get-CimInstance Win32_Process | Where-Object {
      $cmd = [string]($_.CommandLine)
      if ([string]::IsNullOrWhiteSpace($cmd)) { return $false }
      if ([int]$_.ProcessId -eq [int]$currentPid) { return $false }
      $isHostAgent = $cmd -like "*host-agent.ps1*"
      $usesPort = $cmd -like ("*-Port {0}*" -f $port)
      return ($isHostAgent -and $usesPort)
    }
    foreach ($process in $processes) {
      try { Stop-Process -Id ([int]$process.ProcessId) -Force -ErrorAction SilentlyContinue } catch {}
    }
  } catch {
    # Best effort cleanup. The new process will still fail health check if the port is occupied.
  }
  Start-Sleep -Milliseconds 700
}

function Resolve-AnalyticsRepoRoot {
  $candidates = New-Object 'System.Collections.Generic.List[string]'
  foreach ($value in @($env:ERP2_ANALYTICS_ROOT, "D:\dev\ERP2-analytics", "C:\dev\ERP2-analytics")) {
    if (-not [string]::IsNullOrWhiteSpace($value) -and -not $candidates.Contains($value)) { $candidates.Add($value) | Out-Null }
  }
  foreach ($root in $candidates) {
    $startScript = Join-Path $root "tools\start-host-agent.ps1"
    if (Test-Path -LiteralPath $startScript) { return $root }
  }
  return $null
}

Write-Host ""
Write-Host "Host Agent ?�행???�인?�는 중입?�다..." -ForegroundColor Cyan
Write-Host (" - install: {0}" -f $PSScriptRoot)
Write-Host (" - health target: http://127.0.0.1:{0}/health" -f $Port)
Write-Host ""

$pwshExe = Resolve-PowerShellExe
# Re-running the launcher is an explicit restart. Stop stale repo/standalone/worker
# processes first so old Host Agent code cannot keep claiming collector jobs.
Stop-ExistingHostAgents -port $Port

$repoRoot = Resolve-AnalyticsRepoRoot
$repoAgent = if ($repoRoot) { Join-Path $repoRoot "tools\host-agent.ps1" } else { $null }
$preferRepo = $false
try {
  $protocolText = if ($null -ne $ProtocolUrl) { [string]$ProtocolUrl } else { "" }
  $text = [Uri]::UnescapeDataString($protocolText)
  $preferRepo = ($text -match "(^|[?&/])mode=repo($|[&/])") -or ($text -match "start-repo")
} catch {}

$agent = $installedAgent
$launchMode = "standalone"
if ($preferRepo) {
  if ($repoAgent -and (Test-Path -LiteralPath $repoAgent)) {
    $agent = $repoAgent
    $launchMode = "repo"
  } else {
    Write-Host "repo Host Agent를 찾지 못했습니다. standalone 설치본으로 실행합니다." -ForegroundColor Yellow
    Write-Host (" - requested protocol: {0}" -f $ProtocolUrl) -ForegroundColor Yellow
    Write-Host (" - repo root: {0}" -f $repoRoot) -ForegroundColor Yellow
  }
}

Start-Process -FilePath $pwshExe -ArgumentList @(
  "-NoProfile",
